  "$.text.mining.Session": {
    "fullName": "$.text.mining.Session",
    "kind": "class",
    "description": "$.text.mining.Session represents a Text Mining session. Caution The information in this section applies to a feature that is included in the component SAP HANA Advanced Data Processing. To make use of this feature, you must have purchased a license to use SAP HANA Advanced Data Processing.",
    "children": [],
    "members": [],
    "methods": [
      {
        "name": "categorizeKNN",
        "params": [
          {
            "name": "p",
            "type": "Record<string, any>",
            "description": "Encapsulates categorizeKNN parameters."
          }
        ],
        "returnType": "$.text.mining.Session.CategoryResult[]",
        "description": "Given an input document, this function returns the top-ranked category values for the given category set columns in the reference data, using the KNN (K Nearest Neighbors) method. ! Security note For this and the subsequent text mining functions. The following 4 parameters are SQL expressions. The user application needs to take responsibility for blocking any potentially malicious values from being used: inputDocumentSubquery inputDocumentCondition documentRestriction termTypeRestriction"
      },
      {
        "name": "getRelatedDocuments",
        "params": [
          {
            "name": "p",
            "type": "Record<string, any>",
            "description": "Encapsulates getRelatedDocuments parameters."
          }
        ],
        "returnType": "$.text.mining.Session.DocumentResult[]",
        "description": "Given an input document, this function returns the top-ranked related documents from the reference data, based on co-occurrence statistics of terms."
      },
      {
        "name": "getRelatedTerms",
        "params": [
          {
            "name": "p",
            "type": "Record<string, any>",
            "description": "Encapsulates getRelatedTerms parameters."
          }
        ],
        "returnType": "$.text.mining.Session.TermResult[]",
        "description": "Given an input term, this function returns the top-ranked related terms from the reference data, based on co-occurrence statistics."
      },
      {
        "name": "getRelevantDocuments",
        "params": [
          {
            "name": "p",
            "type": "Record<string, any>",
            "description": "Encapsulates getRelevantDocuments parameters."
          }
        ],
        "returnType": "$.text.mining.Session.DocumentResult[]",
        "description": "Given an input term, this function returns the top-ranked documents from the reference data that are deemed relevant to the term."
      },
      {
        "name": "getRelevantTerms",
        "params": [
          {
            "name": "p",
            "type": "Record<string, any>",
            "description": "Encapsulates getRelevantTerms parameters."
          }
        ],
        "returnType": "$.text.mining.Session.TermResult[]",
        "description": "Given an input document, this function returns the top-ranked keyphrases or relevant terms from the reference data, i.e., the terms that saliently describe the document. Keyphrases are used to summarize, characterize and provide thematic access to data."
      },
      {
        "name": "getSuggestedTerms",
        "params": [
          {
            "name": "p",
            "type": "Record<string, any>",
            "description": "Encapsulates getSuggestedTerms parameters."
          }
        ],
        "returnType": "$.text.mining.Session.TermResult[]",
        "description": "Given an input term initial substring, this function returns the top-ranked terms from the reference data that complete that initial substring. Term suggestion is used to present a user with likely search terms as the user enters characters within a search application."
      },
      {
        "name": "initialize",
        "params": [
          {
            "name": "p",
            "type": "Record<string, any>",
            "description": "Encapsulates initialize parameters."
          }
        ],
        "returnType": "void",
        "description": "This function initializes (or re-initializes) Text Mining for the reference table and column linked to the TextMiningSession object. This creates the Term-Document matrix and other configuration context data that is needed for Text Mining functions. The Text Mining context is specific to the reference data, but it is persistent and global for all users. The configuration context specified at initialization time serves later as defaults for unspecified parameters when Text Mining functions are invoked on the given reference data. ! Advanced function This function is typically not used. Initialization of Text Mining is normally done separately when the full text index is created for a given reference table and column. Since the Text Mining context is persistent and global for all users, that is the best way to assure consistent results and avoid confusion. This initialize() function provides a way to directly initialize Text Mining for development purposes or special customer applications. If this function is used carelessly, it can unexpectedly affect other running applications."
      }
    ],
    "constructors": [
      {
        "name": "Session",
        "params": [
          {
            "name": "p",
            "type": "Record<string, any>",
            "description": "Encapsulates constructor parameters."
          }
        ],
        "returnType": "$.text.mining.Session",
        "description": "The Session object represents a Text Mining session. This constructor function creates a Text Mining session object linked to the given reference table and column. Text Mining functions can subsequently be invoked using this object and they will use this linked reference data and the configuration parameters it was initialized with. Multiple such objects can be created to handle multiple sets of reference data. This function does not initialize Text Mining for the reference table and column. Initialization is done separately, typically when the full text index is created for the table and column. Note that it is possible to use a custom XS SQL connection to access the Text Mining reference table as a different user (see \"Creating Custom XS SQL Connections\" in the SAP HANA Developer Guide)."
      }
    ]
  },
